syntax.mysql:
func(args) OVER (
  [PARTITION BY expr [, expr ...]]   -- split rows into groups; omit = one group
  [ORDER BY expr [ASC|DESC] [, ...]] -- order rows inside each group (needed by ranking / value / running functions)
  [frame_clause]                     -- which rows around the current row count (see Window frames)
)

